    "ng.note": "最初のパーティーは<b>レア1人・マジック1人・ノーマル1人</b>です。最初の画面から各英雄の<b>等級</b>が分かります。ユニーク15人は固定の顔ぶれで、開始時の抽選では消費されません。<br>各能力値を個別に抽選しますが、<b>合計は等級ごとの範囲内</b>に収まります。等級間で範囲が<b>重なる場合もあります</b>。等級によって合計のほか、能力値の<b>分布</b>も異なります。レアとノーマルは比較的均等で、マジックは<b>一つの能力が突出</b>することがあります。装備やレベルアップで能力値そのものは増えず、ここで決めた値は<b>ずっと変わりません</b>。<br><b>等級差は最後まで残ります</b>。全英雄のレベル上限は同じですが、レベルアップでは能力値が増えないので、<b>最初の配分を最後まで引き継ぎます</b>。<br>主となる大罪は大罪マスタリー（タブ1）と派遣適性を決めます。装備との相性（セットポイント）は<b>廃止</b>され、パーティー戦術に移りました。<br>引き直しは<b>何度でも無料</b>です。最初の選択で資源を賭ける必要はありません。<br><b>検討中の項目</b>：各等級の範囲・分布・出現率（いずれも暫定値）、特性の効果（現在は名称のみ抽選）、クラスによる得意能力値の偏り、大罪とクラスの重複の可否。",
