    "pro.skip": "スキップ",
    "pro.begin": "始める",
    "pro.s1.h": "玉座",
    "pro.s1.b": "地獄には王がいた。大悪魔バアルだ。\n\nこの地のすべては彼のものだった。\nバアルは自らの七つの感情をしもべたちに分け与えた。\n憤怒、嫉妬、強欲、怠惰、暴食、色欲、傲慢。\n\n玉座の下で、七人のしもべが王の命を待っていた。",
    "pro.s2.h": "裏切りの夜",
    "pro.s2.b": "ひときわ闇の深い夜、七本の刃がバアルの背に突き刺さった。\n\n振り向くと、そこには見知った顔が並んでいた。\n反撃しようとしたが、力はすでに奪われていた。\n\n誰かが鍵を渡したのだ。バアルは押し戻され、足元の地面が崩れた。\n玉座も、見下ろす顔も、地獄の赤い光も、頭上へと遠ざかっていった。",
    "pro.s3.h": "転落",
    "pro.s3.b": "振り向いたときに見た顔が、一つ、また一つと薄れていった。\n刃は本当に七本だったのか。もう分からなかった。\n\n肉が焼けるように痛んだ。体に烙印が刻まれていた。\n\n再び戦うには、自分の命令で武器を取る者が必要だった。\n\n<em>この背を刺したやつらを、一人ずつ見つけ出す。</em>",
    "pro.s4.h": "村",
    "pro.s4.b": "目を開けると、人間の老人が口に少しずつ水を含ませてくれていた。\n人間になったバアルは、自分の力で頭を起こすことすらできなかった。\n\n何日もの間、村人たちは自分のパンをちぎって彼に食べさせた。\n\n<em>なぜこいつらは俺を生かそうとする？</em>",
    "pro.s5.h": "炎",
    "pro.s5.b": "村から炎が上がった。サタンの軍勢が来たのだ。\nかつて地獄から追放した相手が、ここまで追ってきた。\n\nバアルは村で集めた傭兵たちに向かって手を上げた。",
    "pro.s5.q": "「道を開けろ。サタンを追うぞ」",
    "pro.end": "第1章　憤怒／燃えさかる戦場",
