    "exp.repeat.tip": "オン:このエリアのステージを抜ける・オフ:各勝利後に次のステージに移動する",
    "exp.repeat.sub": "エクスカーション <b>決して止まらない</b> — 実行が次の1つの頭を短く終わらせるとき。<b>リトリート</b> または <b>ゲームを閉じる</b> それらを停止する・実行 <b>ゲームが開いている間だけ</b><br>次回ステージへ向かう勝負・敗退(パーティーダウン・タイムアウト)は、再び同じステージを走る・チャプターボスへの喪失が前のステージに戻る・ <b>繰り返して</b> パーティは、エリアのステージI→II→III→Iを介してループします。<b>オフで</b> 順に次のステージに移動します(次がロックされている場合、再び同じステージ·次の難易度をロック解除する上司は、その難しさの1-1に移動)·すべてのステージは、新しい実行です, そう誰もが回復しました",
