    "mm.tut": "チュートリアル",
    "mm.tut.c1_depart.tab": "遠征は、相手を戦いに送り出します。バトルは自分の目で再生し、在庫に積んだギアや素材がみつかります。",
    "mm.tut.c1_depart.place": "戦うためにエリアを選択します。. ステージを勝ち抜くと、次のステージに進みます。最後のステージでエリアボスが待っています。",
    "mm.tut.c1_depart.send": "デプロイすると、パーティーが自動的に対戦します。ゲームが開いている間、条件の進行状況。研究室では、離れながら作業を続けていきます。",
    "mm.tut.c1_storage.tab": "建設業で金を費やし、施設を造り、新たな機能のロックを解除します。",
    "mm.tut.c1_storage.lot": "建物を選択し、右側のパネルのアンロックを見ることができます。研究室のリソースラインをビルドストレージが開きます。",
    "mm.tut.c1_storage.build": "建物のストレージは、ゲームが閉じている間も材料を集め続ける研究室のリソースラインを開きます。費用を払って、一度に建てられます。",
    "mm.tut.c1_reg.tab": "研究室は、ゲームを閉じながら作業を続けます。実行したい各行に少なくとも1つの英雄を割り当てます。",
    "mm.tut.c1_reg.line": "空のスロットをクリックすると、リソースラインの英雄を選択します。",
    "mm.tut.c1_reg.hero": "割り当てられた英雄は、まだ遠征に行くことができます。リソースラインの各英雄は、材料をより速く収集するのに役立ちます。",
    "mm.tut.c1_reg.apply": "英雄を割り当て、生産を開始するために[適用]を選択します。返却時にお持ちの素材が入荷いたします。",
