    "nt.guide.retryPreparation": "レビュー 遠征の準備",
    "nt.retry.detail": "パーティー {party}・{stage}・{n} はっきりと走る。ギア、マスタリー、ポションを見直し、または以前のステージを農場で収穫します。",
    "ch.salvageHint": "歯車を右クリックし、[ロック]を押してロックまたはロック解除します。ロックされたギヤは決して救いません。[分解]を押して、分解 Boxを開きます。歯車をクリックして配置するか、レアリティ、レベル、ベース列から選択し、マッチングギアが一度に行きます。[今すぐ分解]はそれをほこりにし、ピックをクリアします。いくつかの列で、すべての列が入るギアのみが選択されますので、ベースカラムで高いベースオプションギアを外すことができます。【オートサルベージ】はパーティーごとにセットされます。各レアリティ×スロットセルは、キープ、ベースまたはサルベージを選択し、パーティーの最も低い英雄レベルをはるかに下回るサルベージギアにレベル条件をオンにします。ギアは、レベル条件とそのセルの両方を満たしたときだけ保持されます。ベースセルは、そのスロットのしきい値の上にあるか上にあるベースオプションのみを装備します。ユニークで熟練したギアは、常に保持されます。新しいギアのみチェック — [今すぐ在庫を適用する] を押して、すでに保持しているものを救います。ルールをプリセットに保存して、別のパーティーに読み込みます。",
