    "cs.help": "試練の塔は1階から挑戦します。挑戦できる最上階で勝つと次の階が開きます。負けても進行状況は保たれ、クリア済みの階には何度でも挑戦できます。<br>各階の対戦相手は固定です。精鋭の群れやステージボスを倒した先では、ライバルの英雄パーティーや章ボスが待っています。階数が敵の基本レベルになります。",
