    "ar.rules": "デュエルルール",
    "ar.help.rating": "闘技場は格付けでランクされています。増加し、それを損失します。; より強い相手の賭けは、より多くの利益を獲得し、それらにコストを削減します。. リーグを上に移動するし、しきい値を渡します。<br>ご意見・ご要望等は、下記よりお寄せください。各カードに+ / −が勝つか負けると、あなたの格付けがどれだけ変化するかです。それぞれの決闘の後に新しい相手が現れます。<br>あなたの格付けは、デュルが始まる瞬間を解決します - リプレイを閉じると結果を変更しません。他のプレイヤーが登録した防衛関係者です。",
