    "ar.last": "最後のデュル: {result} · {sec} s",
    "ar.help": "保存されたパーティーを選択して、その英雄とフロントまたはバックランクを使用します。パーティータブでメンバーと構成を編集します。3つの英雄を割り当て、決闘を始める。<br>シングルラウンドは、個々の統計量、ギアとスキルプラス選択したパーティーの戦術やポションとあなたの図鑑ボーナスを使用します。相手は自分の戦術やポションを使っています。引く時間制限が終わります。<br>デュエルは、報酬なし、コーデックスキルやリソースコストなしで、遠征の独立して実行します。飲酒はお持ちの商品からお預かりしておりません。闘技場格付けと試行錯覚の塔が保存されます。リロード時にピックされた相手と最後の結果リセットが行われます。",
