    "dp.help": "ラインは時間の上の作り出します <b>割り当てられた英雄とだけ</b> — ゲームが閉じている間でも(ゲームを閉じるまで) {h}h ・ スロットがいっぱいになるまで検索)<br>ノードと<b> 研究 </b>を選択してレベルを上げます。時間がかかりますし、Laborは<b>を1回実行します。</b> ·全額返金のキャンセル · ラボランクが新しいノードを開きます<br>各英雄 <b> がリソースまたはギャンブルデンに </b> を割り当てた <b> 1 シェア </b> (1 英雄 100% ・ 2 200% ・ 3 300%), 検索の各英雄実行 <b> 自分の時計 </b>, そして、統計は、上のボーナスを追加します — ラックジャックポット · インテリジェンス研究の時間 · チャリマの質 · 死亡率 (長い割り当てられた) · ライン上の統率ピアー · 敏捷性研究コスト. 課題は、遠征や探索を中止しません。<br><b> トレーニング </b> ラインは、その割り当てられた英雄に XP を与えます (ロスターのトップレベルまで) · <b> ギャンブルデン </b> ラインは、酒場のギャンブルデンと共に開きます",
