    "exp.form.back": "後列",
    "exp.cantDepart": "このパーティーは出発できません。",
    "exp.party.note": "失われたHP <b>そしてダウンされた英雄は自由で、直ちに元通りにされます</b> 実行終了時 — コストは <b>その残りの部分のためのシンナーパーティー</b><br>パーティーのバフはスキル効果であり、スタットではありません - 統率は対比係数を持っていません",
    "exp.bench.h": "控え",
    "exp.bench.note": "<b> 構造はディスパッチではありません </b> — それは英雄を送らずに実行されますので、 建設タブはそれを所有しています<br>派遣された英雄はロックされていない - いつでもリコールし、<b>プロラータを時間経過 </b> を受け取る",
    "exp.commission.h": "依頼",
    "exp.commission.note": "手数料は、 <b>あなたが取る目標</b> — バトルフィールドが開いていない。ボードから1つを選んで、それ自体を埋めます <b>あなたがすでに何をしているかの上に</b><br>各カードは、その使命を設定する<b> 1の大罪 </b>を運びます - 怒りの敷設(モンスター・エリツ・ボス)・エンビー読書スキルブック・採用英雄・給餌・収集ギア・スロトミー集会・グルトニーエンハンシング・クラフト。<b> あなたがその活動を行うことができれば </b>、その大罪のカードがボードに参加します<br><b> ギャザリングはオフラインでも </b> を上回る - ラボの出力はそれを満たします。送金するパーティーはありませんし、手数料のみの戦場はありません<br>等級は<b>ノーマル・マジック・レア</b>です — 上位グレードはターゲットを狭くします(1章・1位・1グループ)、より少なく頻繁に出現し、より多くの金を支払う。ターゲットは、現在到達できる場所からのみ来ています<br><b> カード</b>の支払いを受諾 — アクティブなコミッションに、セット番号のみを保持することができます。ということは、「自分が取っている」という決定を成し遂げることです。<br>何が起こるかだけ <b>受付完了後</b> カウント — 勝ったラウンドで殺す · 手やオートサルベージ(フルバッグのオーバーフローなし)によって行う救済策による救済 · 研究室からの材料 · 試みを強化する (あまりにも失敗) · クラフト ・ スキルブックを読む · 英雄は、勝ったラウンドから到着したギア · すべてのパーティーはそれを埋める · <b>期限はありません</b><br>各 [受け取る] は、図鑑 の <b> 大罪 </b> に 1 つを追加します。<br>満たすと、<b> [クレーム] </b>は金・<b> [Abandon] </b>の費用は発生しませんが、進行中 — 新しいカードは空の場所を取ります<br><b> 委員会レベル </b> — 研究所検索ラインの <b> 委員会 </b> ノードの研究によってそれを上げます (次のレベルには、完了したコミッションのセット番号が必要です)。より高いレベルは、<b>新しく投稿されたカード</b>は、より多くのために尋ねて、より速く上昇する金でより多くのお金を払う - 研究が終了したときに、あなたが受け入れられていないすべてのカードは新しいレベルで再ロールされ、受諾された手数料は、その進捗を維持します",
    "exp.zones.h": "遠征ゾーン",
    "exp.zones.sub": "チャプター = {p} エリア・各エリアにステージI・II・III=1ラン=1ステージ・{r}ラウンド(最後のエリアは、チャプターボス単独で1ラウンド)があります。",
