    "exp.story.noLeader": "A 傭兵",
    "exp.zones.note": "ゾーンの罪は、その罪の苦難の低下体重を上げます - ターゲット農業の軸線<br><b> 固定構造、ランダムなコンテンツ </b> — ステージ III はエリート {e} / ボス {b} をレイアウトします。<b> 段階 I ・ II は、ラウンドでエリートを持っています {b} あまりにも </b> (上司なし); モンスターミックスとエリート特性が各実行を再ロールします。モンスター、背景と要素は、エリアの3つのステージによって共有され、レベルがステージによって上昇します。<b>最後の領域は、チャプターボス</b>に対する単一のラウンドです<br>初期にリトリート <b> すべてのルートを保持します。</b>. コストは<b>で、走行の残りの部分のためのシンナーパーティー </b>プラスノークリア(次のステージはロックされています)",
