    "tc.name.guardian": "守護者",
    "tc.desc.guardian": "前列で生存している味方英雄がリーダーだけのとき、味方後列の被ダメージが{p1}減少する。",
    "tc.name.unity": "一致団結",
    "tc.desc.unity": "味方英雄が{p2}人以上生存している間、味方英雄の直接ダメージが{p1}増加する。",
    "tc.name.dying_curse": "最期の呪い",
    "tc.desc.dying_curse": "味方英雄が倒れるたび、敵の防御力と各元素耐性のうち正の値が現在値から{p1}減少する。ラウンドごとに最大{p2}回。",
    "tc.name.giant": "巨人",
    "tc.name.desperate_charge": "決死の突撃",
    "tc.name.mutual_cover": "盾の陣",
    "tc.desc.mutual_cover": "前列2人・後列1人で配置すると、前列の英雄が受けるダメージの{p1}をもう一人の前列の英雄が肩代わりする。",
    "tc.name.open_order": "散開陣形",
    "tc.name.iron_line": "背水の陣",
    "tc.desc.iron_line": "出撃する英雄を全員前列に配置すると、最初に致命的なダメージを受けた味方の英雄がHP1で踏みとどまる。戦闘につき1回。",
    "tc.name.pursuit": "追撃陣",
    "tc.desc.pursuit": "全員を前列に配置すると、単体攻撃は狙える敵のうち残りHPの割合が最も低い敵を優先する。",
    "tc.name.hammer_anvil": "鶴翼の陣",
    "tc.desc.hammer_anvil": "前列2人・後列1人で配置すると、敵前列のユニットが受けるダメージの{p1}を敵後列のユニットが均等に分担する。",
    "tc.name.field_medics": "後方救護隊",
    "tc.desc.field_medics": "前列2人・後列1人で配置すると、前列の2人が受ける回復量が{p1}増加する。",
    "tc.name.vanguard_barrier": "先鋒の防壁",
    "tc.desc.vanguard_barrier": "前列1人・後列2人で配置すると、ラウンド開始時に前列英雄は自身の最大HPの{p1}分のバリアを得る。",
    "tc.name.aimed_fire": "精密射撃",
    "tc.desc.aimed_fire": "前列1人・後列2人で配置すると、後列の2人は単体攻撃のクリティカル率に+{p1}。",
    "tc.name.volley": "集中砲火",
    "tc.desc.volley": "出撃する英雄を全員後列に配置すると、敵の前列ユニットに与えるダメージが{p1}増加する。",
    "tc.name.rapid_deployment": "迅速展開",
    "tc.desc.rapid_deployment": "全員を後列に配置すると、ラウンド開始時に各英雄の行動ゲージが{p1}たまる。",
    "tc.desc.open_order": "味方英雄を全員後列に配置すると、範囲攻撃で受けるダメージが{p1}減少する。",
    "tc.desc.desperate_charge": "味方英雄を全員前列に配置すると、戦闘中、敵に与えるダメージが{p1}増加する。",
    "tc.desc.giant": "味方英雄が1人だけ生存している間、その英雄の基本能力値7種が{p1}増加する。",
    "tc.name.baggage": "輜重隊",
    "tc.desc.duel": "味方リーダーの単体攻撃は敵リーダーだけを狙う。敵リーダーが倒れると通常の対象選択に戻る。",
    "tc.desc.wedge": "味方リーダーの単体攻撃が命中すると、対象に{p1}秒間印を付ける。味方の単体攻撃は印の付いた敵を優先する。",
    "tc.desc.trojan": "各ラウンド開始後{p1}秒間、味方の後列は行動できない。その後、後列の単体攻撃は敵の後列を狙う。",
    "tc.desc.charge": "ラウンド開始時、味方の前列が直ちに行動する。後列の初回行動は{p1}秒遅れる。",
    "tc.desc.shieldwall": "味方の後列が受ける直接ダメージの{p1}を、生存している前列の味方が分担する。",
    "tc.desc.guard": "味方リーダーが受ける単体攻撃の直撃ダメージの{p1}を、現在HPが最も高い味方が肩代わりする。",
    "tc.desc.turtle": "各ラウンド開始後{p1}秒間、味方全体の被ダメージが{p2}、攻撃速度が{p3}低下する。",
    "tc.desc.retreat": "前列の英雄のHP割合が各ラウンドで初めて{p1}を下回ると、後列で残りHP割合が最も高い味方を探す。その味方のHP割合が自身より高ければ、ラウンド終了まで位置を入れ替える。",
    "tc.desc.poison_arrow": "味方が与える物理ダメージの{p1}を毒ダメージに変換する。",
    "tc.desc.fire_arrow": "味方が与える物理ダメージの{p1}を火炎ダメージに変換する。さらに{p2}の確率で対象を炎上させる。",
    "tc.desc.baggage": "味方がポーションを飲むと、その回復量の{p1}に相当するHPを、生存しているほかの味方が分け合う。",
