    "sk.cool": "クールダウン {s} s",
    "sk.cdrShort": "クールダウン削減",
    "sk.slots.note": "あなたのターンが来るとき: <b> 待望の準備ができてスキル </b> → タイは <b> スロット注文 </b> → 準備が整ったら、基本的な攻撃を意味します。<b> マジック武器は基本的な攻撃を持っていません </b> — 何も準備ができていないと、ゲージはフルを待って、スキルが準備される瞬間をキャストします<br>1ターンあたりの1つのアクション。スキル <b> は、攻撃をオンにし、マナがない </b> を置き換える - アクション自体は唯一のコストです<br>リアルタイムで実行されるクールダウン<br>基本的な攻撃は常に<b>物理的</b>であり、スキルのみの要素的なダメージ<br>スキルは、<b>クラス</b>に属しています。各スキルは正確に1つのクラスに座っています。英雄スロットは、<b>の英雄クラスのプール</b>と<b>から学んだスロットから</b>を読む本を読みます。<b>攻撃、ヒール、召喚</b>スキルは、任意のスロットでそのスキルのクラスの武器を必要とします。<b>バフとデバフ</b>そのような叫び、オーラや祝福はどんな兵器と一緒に働きます<br>⚠ 名前と形状が解決されますが、<b>のマルチプライヤー、ヒット、クールダウン、および期間は公開されません </b> — 現在の数字はプレースホルダーです",
    "sk.sinTree": "{sin} マスター",
    "sk.sinTree.sub": "全{sin}英雄のシェア",
    "sk.sinTree.missing": "<b> 一番下行(反応)は方向性を持ちませんが、数字</b>は「X時、Y」はトリガー周波数でスケールし、まだそのためのヤスティックはありません。",
    "sk.mastery": "{cls} マスター",
    "sk.mastery.missing": "クラスマスタリーは、<b> の同じ構造 </b> を 大罪 マスタリー として使用しています。<b> 各クラスは、トップ行で 3 つの確認されたノードを持っています。</b><br><b> 装備されているギアは、以下の3つのノードをアクティブにします。</b>高速武器は、ダメージ%をアクティブにし、武器が攻撃スピードを遅くし、クラスアーマータイプは鎧 マスタリーを起動します。マッチングギアなしでランクを投資することができますが、効果は非アクティブにとどまります。<br>再アクティブ・ボトムの行は、まだ設計されていません。",
    "sk.advTree": "アドバンスト・マスター",
    "sk.advNeed": "アドバンス",
