    "sk.adv.band.line": "スキルアップ",
    "sk.adv.lineNeed": "高度なスキルを学ぶ",
    "sk.adv.band.common": "一般的なマスター",
    "sk.advTree.missing": "<b> 1つの共有スキルポイント</b>のためのパスの3つの主要なスキルの1つを学びます。ポイントはLv1から全てのレベルに、大罪とクラス マスタリーで共有されます。<br>主は英雄Lv30/35/40/45/50でLv1–5の鍵を開けます。特別、変種、および究極の枝は現在後に来ています。",
    "sk.lockedSuffix": "(ロック)",
    "sk.grid.note": "マスタリー は分岐ツリーではなく、上から下へ <b> の積み重ねが </b> — <b> 上行が最初に開き、後方 </b><br>セルをクリックし、ランクを追加します。セルはまだ表示できません <b> 彼らは</b>を必要とするレベル. <b>空の細胞は、unwritten設計です </b>; 遅延フレームが滞在するので、これはどこまで行くかを見ることができます",
    "tv.h": "ハイレ英雄",
    "tv.sub": "まれな層 — クラス × 罪 × 到着時に転がる特性",
    "tv.reroll.note": "酒場の転がりは<b>アイテムで、英雄</b>を栽培しています。ローリングループは<b>レアティエ</b>に住んでおり、35個の罪×クラスの組み合わせをすべて提供しています。",
    "tv.tiers.note": "<b> 独自の </b> — 固定名、クラス、および罪 + 1 署名スキル (英雄排他的)。1 つのコピーあたりのロスター。ベースゲームで15個入(クラス3個)<br><b> レア </b> — すべてのロール、共有プールから割り当てられたシグネチャスキル。全35個の罪×クラスセルをカバー",
