    "cx.note": "モンスターから集められたコーデックスEXPが累積的なしきい値を渡るたびに、 <b>コーデックスレベル</b> 増加し、より多くのボーナス効果を開く - 初期のもの(キルEXP・それへのダメージ・チャンスをドロップ)が適用されます <b>そのモンスターだけに</b> · 最後の 1 は加えます <b>モンスターの戦闘オプションをパーティー全体に</b> グッドのために <b>農業は、コーデックスを押します</b><br>各キルのコーデックス EXP は、遠征の難易度で設定されます。より高い難しさは、より速く埋めます。また、獲得したラウンドからのみ殺します。<br>モンスターの物語とレベルマイルストーンを見るためにカードをハバー",
