    "bt.note": "時計は許可されていますが、<b>は絶対に必要としません </b> — 速度はペースだけ変化します。ランニング中にギアとスキルツリーの変更は、<b>を一度に</b>を適用します。, ボスの戦いの間にを含みます · 各ラウンド <b>は、あなたがそれを勝つ瞬間を支払います </b> (バッグ・金・XP・コーデックス).<br><b>リトリート</b>は、遠征を停止します。それは進行中のラウンドをドロップし、次の実行がカウントダウンしている間、勝ったラウンドが与えた·プレスされたものを保持し、次の実行は出ていません。ゲームを閉じると、スポットの遠征をカットします。",
