    "같은 시간에 {v}방 더 긁는다\t{v} more ticks in the same time": "同じ持続時間内の攻撃回数が{v}回増える",
    "방마다 후열 무작위 하나에게 조각({v} · 결빙)\tEach tick a shard hits a random back-row enemy ({v} · Freeze)": "攻撃のたびに無作為な後列の敵1体に氷片を放つ（威力{v}、凍結を付与）",
    "구름 속에서 틱마다 피해 {v}씩 증가\tDamage grows by {v} each tick inside the storm": "吹雪の中ではダメージが発生するたびに威力が{v}ずつ上昇",
    "구름 속 적이 받는 피해 {v} 증가\tEnemies in the storm take {v} more damage": "吹雪の中にいる敵の被ダメージが{v}増加",
    "보호막 증가\tStronger shield": "バリアの耐久値増加",
    "물리 피해도 {v} 막는다\tAlso absorbs {v} of physical damage": "物理ダメージも{v}防ぐ",
    "깨질 때 깬 적에게 냉기 {v}(결빙)\tWhen broken, deals {v} Cold to the breaker (Freeze)": "バリアを破った敵に{v}の冷気ダメージを与え、凍結させる",
    "「한 번 더」 최대 +{v}\t\"Strike again\" cap +{v}": "再攻撃の上限 +{v}",
