    "쿨타임 감소\tShorter cooldown": "クールダウン短縮",
    "쓸 때마다 다음 노바 {v} 세진다(최대 {a}겹 · 라운드마다 처음부터)\tEach cast makes the next Nova {v} stronger (up to {a} · resets each round)": "使用するたびに次のノヴァの威力が{v}上昇（最大{a}スタック、ラウンドごとにリセット）",
    "맞은 적 번개 저항 {v} 감소(최대 {a}겹)\tLowers Lightning Resistance by {v} (up to {a} stacks)": "命中した敵の雷耐性を{v}低下させる（最大{a}スタック）",
