    "하늘 탑 폐허\tSky Tower Ruins": "スカイタワー遺跡",
    "성물 상단\tRelic Caravan": "レプリカキャラバン",
    "불길을 피해 마을 사람들이 숨던 굴입니다\n두고 간 짐과 무기가 아직 그대로 쌓여 있습니다\tVillagers hid here from the fires\nThe packs and weapons they left are still piled inside": "火からここに隠れた村家\n左のパックと武器は、まだ内部に積まれています",
    "전쟁의 첫 화염이 오른 봉화대입니다\n그을린 돌벽에 옛 군령이 아직 새겨져 있습니다\tThe beacon where the war's first fire was lit\nOld orders are still carved into the scorched stone": "戦争初の火災が点灯したビーコン\n古い注文はまだ石畳に刻まれています",
    "불탄 들을 가로질러 곡식을 나릅니다\n굶주린 자들은 적이든 아군이든 수레부터 노립니다\tHauls grain across the burnt fields\nThe starving of both sides go for the wagons first": "バーントフィールドを横断する粒\n両サイドの星空は、ワゴンが最初に行く",
    "까마귀들이 남의 것을 물어다 쌓는 굴입니다\n반짝이기만 하면 칼날이든 반지든 가리지 않습니다\tCrows hoard what belongs to others here\nAny blade or ring that glints will do": "ここに他の人に所属するものを隠す\nどのブレードや指輪がするのか",
    "우상족이 깎은 나무 가면이 줄지어 걸려 있습니다\n가면마다 다른 누군가의 얼굴을 흉내 냅니다\tRows of wooden masks carved by the Idolfolk\nEach one copies someone else's face": "Idolfolkによって刻まれた木製のマスクの列\n他の人の顔をコピーするそれぞれ",
    "안개 낀 늪 사이로 모피를 실어 나릅니다\n나무들이 서로를 향해 굽어 길이 날마다 바뀝니다\tCarries furs through the misty marsh\nThe trees bend toward one another and the road shifts daily": "ミディ・マッシュを通るキャリーファー\n別の木々と道路が毎日シフトする",
    "도굴꾼들이 무덤에서 파낸 것을 숨겨 두는 굴입니다\n찾으러 돌아온 주인은 아무도 없습니다\tGrave robbers stash their spoils here\nNot one of them ever came back to claim it": "Grave robbers 倉庫 彼らの spoils ここに\n彼らのうちの一人がそれを主張するために戻って来た",
    "모든 길손에게 통행세를 걷던 세관입니다\n무너진 벽 아래에서 장부가 아직 빚을 셉니다\tA customs house that taxed every traveler\nUnder the fallen walls the ledgers still count debts": "すべての旅行者に課税された習慣の家\n倒れた壁の下に、レジャーはまだ債務をカウントします",
    "향신료를 실은 낙타가 줄지어 갑니다\n삯을 올려 부르는 상단 주인이 도적보다 무섭습니다\tA line of camels laden with spice\nThe master who keeps raising the fee is worse than bandits": "スパイスでラデンのラクダのライン\n手数料を上げ続けるマスターは、バンディットよりも悪くなります",
    "길 잃은 원정대가 잠시 쉬어 가던 굴입니다\n내려놓은 짐과 무기 곁에서 그대로 얼어붙었습니다\tA lost expedition stopped here for a short rest\nThey froze beside the packs and weapons they set down": "短い休息のためにここに迷った遠征が止まる\n彼らは、彼らが設定したパックと武器の横に凍らせます",
    "눈에 묻힌 수도원입니다\n필사하던 수도사들이 펜을 쥔 채 얼어 있습니다\tA monastery buried in snow\nThe scribes froze with their pens still in hand": "雪に埋もれた修道院\n筆記は、手元にはまだ彼らのペンで凍っています",
    "개 썰매가 얼음 위로 소금을 끕니다\n잠깐 쉬어 가자는 말이 나오면 그 자리에 멈춥니다\tDog sleds haul salt across the ice\nWhoever suggests a short rest stops there for good": "犬は氷を渡る塩をそります\n誰が短い休憩が良いためにそこに停止することを示唆しています",
    "삼킨 것을 끝내 다 소화하지 못한 굴입니다\n벽 틈마다 씹다 만 갑옷과 칼이 박혀 있습니다\tThe cave never finished digesting what it swallowed\nHalf-chewed armor and blades jut from every crack": "洞窟は、それが嚥下したものを消化し終えません\nハーフカットの鎧とブレードは、すべての亀裂からジュート",
    "땅이 꺼지며 통째로 삼켜진 마을입니다\n식탁에는 차려 둔 음식이 아직 굳어 있습니다\tA village swallowed whole when the ground gave way\nThe meals set out still harden on the tables": "地面が道を与えたとき、村全体を飲み込む\n食事はテーブルにまだ固まっている",
    "동굴 마을로 식량을 실어 나릅니다\n도착할 때마다 실은 것보다 먹어 치운 것이 많습니다\tHauls provisions to the cave towns\nMore gets eaten on the way than ever arrives": "洞窟の町へのオウルス規定\n今まで到着するよりも、もっと食べられる",
    "궁전의 포도주를 익히던 굴입니다\n취해 잠든 손님들의 장신구가 바닥에 흩어져 있습니다\tWhere the palace aged its wine\nJewelry of guests who drank themselves to sleep lies scattered": "宮殿がワインを熟成させた場所\n眠りにこだわったゲストのジュエリーは、散らばる",
    "춤이 멈추지 않던 무도회장입니다\n깨진 거울마다 다른 누군가가 춤을 춥니다\tA ballroom where the dancing never stopped\nSomeone else dances in every broken mirror": "踊りが止まらないボールルーム\n他の人が壊れた鏡で踊る",
    "궁전에 바칠 비단과 향을 싣고 갑니다\n짐을 지키던 호위가 하나둘 궁전 쪽으로 사라집니다\tCarries silk and incense meant for the palace\nOne by one the guards drift off toward it": "宮殿のために意味されるキャリーシルクと香\n警備員がその方向に向かって飛び降りる1人",
    "산을 오르던 순례자들이 쉬어 가던 굴입니다\n자격이 없다며 두고 간 칼과 방패가 쌓여 있습니다\tPilgrims rested here on the climb\nSwords and shields lie where the unworthy laid them down": "登りにピルグリムズがここを休む\n剣と盾は、不適格にそれらが下に置いた場所にある",
    "하늘에 닿으려고 쌓던 탑입니다\n무너질 때마다 더 높은 돌에 새 이름이 새겨졌습니다\tA tower raised to reach the sky\nEach collapse left new names carved on higher stones": "空に辿り着くタワー\n各崩壊は、より高い石の上に刻まれた新しい名前を残しました",
    "산꼭대기 신전으로 성물을 실어 올립니다\n짐보다 무거운 것은 주인의 이름값입니다\tHauls holy relics up to the summit temple\nHeavier than the cargo is the owner's reputation": "聖なる神殿までの聖なる遺物\n貨物よりも重いのは、所有者の評判です",
    "모두 전열\tAll Front": "すべての前部",
