    "성장\tGrowth": "成長率",
    "총합이 낮은 대역 · 분포가 넓어 한 축이 크게 튈 수 있음\tLower stat total · a wide spread so one axis can spike": "統計量を下げる · 広いスプレッドなので、1つの軸線はスパイクできます",
    "총합이 높은 대역 · 정규분포라 극값이 드물고 고르게 분포\tHigher stat total · a normal spread so extremes are rare": "統計量が高い · 普通スプレッドなので、極端なことはまれです",
    "이름·직업·죄종 고정 + 고유 스킬 1개(영웅 전용) · 영웅 로스터에 1명만\tFixed name class & sin + 1 signature skill (hero-exclusive) · one per roster": "固定名クラスと罪 + 1 署名スキル (英雄排他的) · 1 人のロスター",
    "총합이 가장 낮은 대역 · 정규분포라 고르게 분포\tLowest stat total · a normal spread so stats come out even": "一番低いスタットの合計・普通スプレッドなので、スタッツも出てきます",
    "고블린 전용 등급 · 모든 능력치가 낮게 시작 · 레벨마다 능력치 하나 성장\tGoblin-only grade · every stat starts low · one stat grows each level": "ゴブリン専用グレード・全スタットが低・1つのスタットが各レベルを成長させる",
    "다혈질\tHot-Blooded": "ホットブラッド",
