    "사냥 표식\tHunter's Mark": "狩人の印",
    "지원 사격\tSupporting Fire": "援護射撃",
    "덫\tTrap": "罠",
    "버티기\tEndure": "忍耐",
    "정화\tPurify": "浄め",
    "리저렉션\tResurrection": "蘇生",
    "천벌\tDivine Punishment": "天罰",
